import { useCallback, useEffect, useMemo, useState } from 'react';
import { useDateContext } from '../contexts/DateContext';
import {
  getRecommendations,
  sendRecommendationFeedback,
  type Recommendation,
  type RecommendationResponse,
} from '../services/api';
import './Recommendations.css';

/**
 * Recommendations produced by the local rule engine.
 *
 * Every card here is generated by a named rule against recorded activity, and
 * every figure in one was computed in Python before the sentence was
 * assembled. The page previously rendered four hardcoded arrays — including a
 * "40% decrease in focus after meetings" that nothing had measured.
 *
 * The `rule_id` / `based_on` provenance line used to be printed under each
 * card to make that difference visible. It is no longer shown: the traceability
 * it provided was for developers, and it read as noise to the person the advice
 * is for. Both fields are still on the API payload, and the rule id remains the
 * feedback key, so nothing that depended on them has changed.
 */

const SECTION_EMPTY: Record<string, string> = {
  immediate: 'Nothing needs your attention right now.',
  insight: 'No notable findings for this day yet.',
  planning: 'Planning suggestions appear once about 10 days of activity are recorded.',
  behaviour: 'Behavioural comparisons need roughly 10 days of history to be meaningful.',
};

const SEVERITY_DOT: Record<string, string> = {
  high: 'var(--color-danger)',
  medium: 'var(--color-warning)',
  low: 'var(--color-success)',
};

const Recommendations: React.FC = () => {
  const { selectedDate, refreshCount } = useDateContext();
  const [data, setData] = useState<RecommendationResponse | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  // Cards the user has acted on this session. Kept locally so the card
  // responds immediately; the authoritative status lives in the database.
  const [resolved, setResolved] = useState<Record<string, string>>({});

  const load = useCallback((refresh: boolean) => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    getRecommendations(selectedDate, refresh)
      .then(response => {
        if (cancelled) return;
        setData(response);
        setResolved({});
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e instanceof Error ? e.message : 'Could not reach the backend.');
        setLoading(false);
      });
    return () => { cancelled = true; };
  }, [selectedDate]);

  useEffect(() => load(false), [load, refreshCount]);

  const sections = data?.sections ?? {};
  const immediate = useMemo(() => sections.immediate ?? [], [sections]);
  const insight = useMemo(() => sections.insight ?? [], [sections]);
  const planning = useMemo(() => sections.planning ?? [], [sections]);
  const behaviour = useMemo(() => sections.behaviour ?? [], [sections]);

  /**
   * Carry out a card's action, then record the verdict.
   *
   * The action runs first so a backend hiccup cannot stop a break starting.
   * Outside Electron `window.electronAPI` is absent and the buttons fall back
   * to recording feedback only — the pages still run under `vite dev`.
   */
  const respond = async (rec: Recommendation, action: 'applied' | 'dismissed') => {
    setResolved(prev => ({ ...prev, [rec.id]: action }));

    if (action === 'applied' && window.electronAPI) {
      try {
        if (rec.action_label === 'Start Break') {
          await window.electronAPI.startBreak(5);
        } else if (rec.action_label === 'Resume Task') {
          const opened = await window.electronAPI.resumeTask(rec.facts);
          if (!opened) {
            // Nothing resolvable in the recorded detail. The card already
            // names the context, which is the larger half of the value.
            setResolved(prev => ({ ...prev, [rec.id]: 'context-shown' }));
          }
        }
      } catch {
        /* The action is best-effort; the verdict below still gets recorded. */
      }
    }

    try {
      await sendRecommendationFeedback(rec.id, action);
    } catch {
      // The verdict is a preference, not a transaction. Losing one to a
      // backend hiccup costs the ranker a training row and the user nothing,
      // so the card stays resolved rather than snapping back.
    }
  };

  if (loading) return <div className="sd-loader">Generating recommendations…</div>;

  if (error) {
    return (
      <div className="recommendations-page sd-fade-in">
        <div className="sd-page-header">
          <h1>Recommendations</h1>
          <p className="subtitle">Generated locally from your recorded activity</p>
        </div>
        <div className="sd-alert sd-alert--warning">
          <span className="sd-alert-icon">⚠️</span>
          <div className="sd-alert-content">
            <h4>Could not load recommendations</h4>
            <p>{error} — check that the backend is running on port 8000.</p>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="recommendations-page sd-fade-in">
      <div className="sd-page-header">
        <h1>Recommendations</h1>
      </div>

      {/* ---- Immediate ---- */}
      <div className="rec-section" style={{ marginBottom: 'var(--space-md)' }}>
        <div className="rec-section-header">
          <span className="rec-section-icon" style={{ color: 'var(--color-primary)' }}>🕒</span>
          <h2>Immediate Suggestions</h2>
        </div>
        <div className="imm-suggestions-list">
          {immediate.length === 0 && (
            <p className="dash-empty">{SECTION_EMPTY.immediate}</p>
          )}
          {immediate.map(rec => (
            <div className="imm-suggestion-card" key={rec.id}>
              <div className="imm-suggestion-content">
                <strong>
                  <span
                    className="legend-dot"
                    style={{
                      background: SEVERITY_DOT[rec.severity],
                      display: 'inline-block',
                      marginRight: 8,
                    }}
                  />
                  {rec.title}
                </strong>
                <p>{rec.why}</p>
                <p style={{ marginTop: 4 }}>{rec.action}</p>
              </div>
              <div className="imm-suggestion-actions">
                {resolved[rec.id] ? (
                  <span className="sd-badge sd-badge--success">
                    {resolved[rec.id] === 'applied' ? '✓ Done'
                      : resolved[rec.id] === 'context-shown' ? 'Context shown above'
                      : 'Dismissed'}
                  </span>
                ) : (
                  <>
                    <button
                      className="sd-btn sd-btn--primary"
                      onClick={() => respond(rec, 'applied')}
                    >
                      {rec.action_label ?? 'Mark Done'}
                    </button>
                    <button
                      className="sd-btn imm-dismiss-btn"
                      onClick={() => respond(rec, 'dismissed')}
                    >
                      Dismiss
                    </button>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ---- Key insights ---- */}
      <div className="rec-key-insights">
        <div className="rec-key-insights-header">
          <span className="rec-icon">!</span>
          <div>
            <h3>Key Insights</h3>
            <span className="rec-subtitle">
              {data?.daily_date
                ? `From your recorded activity on ${data.daily_date}`
                : 'From your recorded activity'}
            </span>
          </div>
        </div>
        <div className="rec-key-insights-body">
          {insight.length === 0 && <p className="dash-empty">{SECTION_EMPTY.insight}</p>}
          {insight.map(rec => (
            <div className="rec-insight-row" key={rec.id}>
              <span
                className={`rec-icon-small ${rec.severity === 'high' ? 'red' : 'green'}`}
              >
                {rec.severity === 'high' ? '!' : '↗'}
              </span>
              <div>
                <strong>{rec.title}</strong>
                <p>{rec.why}</p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ---- Planning ---- */}
      <div className="rec-section">
        <div className="rec-section-header">
          <span className="rec-section-icon">📅</span>
          <h2>Planning Suggestions</h2>
        </div>
        <div className="rec-card-list">
          {planning.length === 0 && <p className="dash-empty">{SECTION_EMPTY.planning}</p>}
          {planning.map(rec => (
            <div className="rec-list-card" key={rec.id}>
              <h4>{rec.title}</h4>
              <div className="rec-list-details">
                <div className="rec-detail-row">
                  <span className="rec-detail-label">Why:</span>
                  <span className="rec-detail-value">{rec.why}</span>
                </div>
                <div className="rec-detail-row">
                  <span className="rec-detail-label">Action:</span>
                  <span className="rec-detail-value">{rec.action}</span>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ---- Behaviour ---- */}
      <div className="rec-section">
        <div className="rec-section-header">
          <span className="rec-section-icon green">📈</span>
          <h2>Behaviour Improvement</h2>
        </div>
        <div className="rec-card-list">
          {behaviour.length === 0 && <p className="dash-empty">{SECTION_EMPTY.behaviour}</p>}
          {behaviour.map(rec => (
            <div className="rec-list-card" key={rec.id}>
              <h4>{rec.title}</h4>
              <div className="rec-list-details">
                <div className="rec-detail-row">
                  <span className="rec-detail-label">Insight:</span>
                  <span className="rec-detail-value">{rec.why}</span>
                </div>
                <div className="rec-detail-row">
                  <span className="rec-detail-label">Suggestion:</span>
                  <span className="rec-detail-value">{rec.action}</span>
                </div>
              </div>
              <div className="rec-card-actions">
                {resolved[rec.id] ? (
                  <span className="sd-badge sd-badge--success">
                    {resolved[rec.id] === 'applied' ? '✓ Applied' : 'Marked not relevant'}
                  </span>
                ) : (
                  <>
                    <button
                      className="rec-action-btn applied"
                      onClick={() => respond(rec, 'applied')}
                    >
                      ✓ Mark as Applied
                    </button>
                    <button
                      className="rec-action-btn"
                      onClick={() => respond(rec, 'dismissed')}
                    >
                      ⊗ Not Relevant
                    </button>
                  </>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Recommendations;
